draw:
var th = p.angle * Math.PI / 180;
var v = p.speed, m = p.mass, D = p.drag;
var g = 9.8;
var Fgrav = m * g * Math.sin(th);
var Fdrive = Fgrav + D;
var Pw = Fdrive * v;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var baseY = H - 26, baseX = 22;
var run = W - 90;
var rise = run * Math.tan(th);
if (rise > H - 70) { run = (H - 70) / Math.tan(th); rise = H - 70; }

// the incline
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(baseX, baseY);
ctx.lineTo(baseX + run, baseY);
ctx.lineTo(baseX + run, baseY - rise);
ctx.closePath();
ctx.stroke();

// angle label
ctx.fillStyle = C.ink;
ctx.fillText(p.angle.toFixed(0) + " deg", baseX + 16, baseY - 6);

// car sits partway up the slope
var f = 0.55;
var cx = baseX + run * f, cy = baseY - rise * f;
var ux = Math.cos(th), uy = -Math.sin(th);
ctx.fillStyle = C.figure;
ctx.save();
ctx.translate(cx, cy);
ctx.rotate(-th);
ctx.fillRect(-16, -13, 32, 11);
ctx.restore();

function arrow(x0, y0, dx, dy, col, label, lx, ly) {
  ctx.strokeStyle = col;
  ctx.fillStyle = col;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x0 + dx, y0 + dy); ctx.stroke();
  var L = Math.sqrt(dx * dx + dy * dy);
  if (L > 1) {
    var hx = dx / L, hy = dy / L;
    ctx.beginPath();
    ctx.moveTo(x0 + dx, y0 + dy);
    ctx.lineTo(x0 + dx - 7 * hx + 4 * hy, y0 + dy - 7 * hy - 4 * hx);
    ctx.lineTo(x0 + dx - 7 * hx - 4 * hy, y0 + dy - 7 * hy + 4 * hx);
    ctx.closePath(); ctx.fill();
  }
  ctx.fillText(label, x0 + dx + lx, y0 + dy + ly);
}

var scale = 52 / Math.max(Fdrive, 1);
var ax = cx + ux * 16, ay = cy - 14 + uy * 16;

arrow(ax, ay, ux * Fdrive * scale, uy * Fdrive * scale, C.accent, "F drive", 4, -4);
arrow(cx - ux * 16, cy - 14 - uy * 16, -ux * D * scale, -uy * D * scale, C.figure, "drag", -34, 14);
arrow(cx, cy - 8, 0, m * g * Math.sin(th) * scale * 0.6, C.ink, "", 0, 0);
ctx.fillStyle = C.ink;
ctx.fillText("mg", cx + 5, cy - 8 + m * g * Math.sin(th) * scale * 0.6);

// velocity arrow above the car
arrow(cx - ux * 10, cy - 30 - uy * 10, ux * 42, uy * 42, C.faint, "v = " + v.toFixed(0) + " m/s", -20, -8);

ctx.fillStyle = C.ink;
ctx.fillText("P = F drive x v", 10, 16);
ctx.fillStyle = C.faint;
ctx.fillText("F drive = mg sin(angle) + drag  (steady speed)", 10, 32);

out.note = "mg sin = " + Fgrav.toFixed(0) + " N, drag = " + D.toFixed(0)
  + " N, so F = " + Fdrive.toFixed(0) + " N and P = " + (Pw / 1000).toFixed(1) + " kW";
